INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(3977, 0, 0, 'You shall pay for this treachery!', 14, 0, 100, 0, 0, 29616, 0, 0, 'whitemane WHITEMANE_TALK_AGGRO'),
(3977, 1, 0, 'Mograine...', 14, 0, 100, 0, 0, 29617, 0, 0, 'whitemane WHITEMANE_TALK_DEATH'),
(3977, 2, 0, 'The Light has spoken!', 14, 0, 100, 0, 0, 29618, 0, 0, 'whitemane WHITEMANE_TALK_SLAY'),
(3977, 3, 0, 'Arise, my champion!', 14, 0, 100, 0, 0, 5840, 0, 0, 'whitemane WHITEMANE_TALK_RESSURETION'),
(59223, 0, 0, 'I will break you.', 14, 0, 100, 0, 0, 29496, 0, 0, 'Korloff_AGGRO'),
(59223, 1, 0, 'You are like... piece of iron...', 14, 0, 100, 0, 0, 29497, 0, 0, 'Korloff_DEATH'),
(59223, 2, 0, 'If you die, you die.', 14, 0, 100, 0, 0, 29500, 0, 0, 'Korloff_firestom'),
(59223, 3, 0, 'My fists are scarlet... with your blood!', 14, 0, 100, 0, 0, 29499, 0, 0, 'Korloff_Fists'),
(59789, 0, 0, 'My endless agony shall be yours, as well!', 14, 0, 100, 396, 0, 27832, 0, 0, 'Thalnos_INTRO'),
(59789, 1, 0, 'No rest... for the angry dead!', 14, 0, 100, 396, 0, 27831, 0, 0, 'Thanlos_SUMMON'),
(59789, 2, 0, 'Seek out a vessel... and return!', 14, 0, 100, 396, 0, 27834, 0, 0, 'Thanlos_EVIC'),
(59789, 3, 0, 'Claim a body, and wreak terrible vengeance!', 14, 0, 100, 396, 0, 27835, 0, 0, 'Thalnos_spirits'),
(59789, 4, 0, 'Can this be... the end, at last...?', 14, 0, 100, 396, 0, 27830, 0, 0, 'Thalnos_dead'),
(59789, 5, 0, '|TInterface\\Icons\\spell_warlock_demonsoul.blp:20|t%s casts |cFFFF0000|Hspell:115297|h[Evict Soul]|h|r on |cFF006EFD$n|r!', 41, 0, 100, 0, 0, 0, 0, 0, 'THALNOS_EVICTED_SOUL_ANN'),
(59789, 6, 0, '|TInterface\\Icons\\ability_warlock_jinx.blp:20|t%s begins to cast |cFFFF0000|Hspell:115147|h[Empowering Spirits]|h|r!', 41, 0, 100, 0, 0, 0, 0, 0, 'THALNOS_EMPOWERED_SPIRIT_ANN'),
(60040, 0, 0, 'My legend begins NOW!', 12, 0, 100, 0, 0, 27527, 0, 0, 'Durand_intro'),
(60040, 1, 0, 'My blade is peerless!', 12, 0, 100, 0, 0, 27530, 0, 0, ''),
(64827, 0, 0, 'Destroy the Piles of Corpses to stop the Zombified Corpses!', 41, 0, 100, 0, 0, 0, 0, 0, 'INSTANCE_INTRO_ANN');
