-- Scarlet Monastery (map 1004): spawns, yells, quest fix and data for the ported Pandaria scripts
-- (tools/bfa/scarlet-monastery.patch). Spawns come from the Pandaria 5.4.8 world DB (alexkulya).
-- This database had 18 permanent Empowering Spirits (Thalnos's level 100 summons), 6 inert Fuel Tanks,
-- 30 Frenzied Spirits instead of 12, half the Purifiers and Zealots, two stray Durand copies, and
-- Thalnos and Durand wandering. Safe to run again.

-- 1) Spawns: replace everything on map 1004 except the entrance Hooded Crusader and the Blade of the Anointed.
DELETE FROM `creature_addon` WHERE `guid` IN (SELECT `guid` FROM `creature` WHERE `map`=1004 AND `guid` NOT IN (10645572, 10645645));
DELETE FROM `creature` WHERE `map`=1004 AND `guid` NOT IN (10645572, 10645645);
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 1004000001 AND 1004000999;
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 1004000001 AND 1004000999;

-- Korloff's patrol (path id = spawn guid) and the two drunk Judicators sitting in the graveyard hall.

-- 2) Yells and raid warnings. Whitemane's old Mograine-fight lines are replaced; the entrance crusader
--    (64827 here, 64838 in Pandaria) gets the Piles of Corpses warning.
DELETE FROM `creature_text` WHERE `CreatureID` IN (59789, 59223, 60040, 3977, 64827);

-- 3) Scripts (tools/bfa/scarlet-monastery.patch). C++ takes over from the old SmartAI rows.
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_scm_hooded_crusader' WHERE `entry`=64827;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_scarlet_flamethrower' WHERE `entry`=59705;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_scm_fuel_tank' WHERE `entry`=59706;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_frenzied_spirit' WHERE `entry`=60033;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_pile_of_corpses' WHERE `entry`=59722;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_scarlet_centurion' WHERE `entry`=59746;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_zombified_corpse', `faction`=1962 WHERE `entry`=59771;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_scarlet_zealot' WHERE `entry`=58590;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_scm_spirit_of_redemption' WHERE `entry`=58592;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='boss_thalnos_the_soulrender' WHERE `entry`=59789;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_fallen_crusader' WHERE `entry`=59884;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_empowering_spirit' WHERE `entry`=59893;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_evicted_soul' WHERE `entry`=59974;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='boss_brother_korloff' WHERE `entry`=59223;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='npc_scorched_earth' WHERE `entry`=59507;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='boss_commander_durand' WHERE `entry`=60040;
UPDATE `creature_template` SET `AIName`='', `ScriptName`='boss_high_inquisitor_whitemane_mop' WHERE `entry`=3977;
DELETE FROM `smart_scripts` WHERE `source_type`=0 AND `entryorguid` IN (64827, 59705, 59706, 60033, 59722, 59746, 59771, 58590, 58592, 59789, 59884, 59893, 59974, 59223, 59507, 60040, 3977);

-- 4) Level scaling for normal difficulty. These NPCs only had a row for difficulty 0, so in the dungeon
--    they rolled a random level between 31 and 90 (the "level ??" Zombified Corpses).
SELECT `Entry`, 1, `LevelScalingMin`, `LevelScalingMax`, `LevelScalingDeltaMin`, `LevelScalingDeltaMax`, `ContentTuningID`, 0
FROM `creature_template_scaling` WHERE `DifficultyID`=0 AND `Entry` IN (59771, 59884, 59930, 59974, 58592);
SELECT 64842, `DifficultyID`, `LevelScalingMin`, `LevelScalingMax`, `LevelScalingDeltaMin`, `LevelScalingDeltaMax`, `ContentTuningID`, 0
FROM `creature_template_scaling` WHERE `Entry`=64827;

-- 5) Spells.
-- Barrel Explosion (clicked Fuel Tank) hits creatures only, never players or other tanks.
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=13 AND `SourceEntry`=114952;
-- Scarlet Resurrection could only target Mograine (old Cathedral); Whitemane now raises Durand.
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=13 AND `SourceEntry`=9232 AND `ConditionValue2`=60040;
-- Spirit Gale (Thalnos) leaves a pool that hurts whoever stands in it (areatrigger 220 had no data).
DELETE FROM `spell_areatrigger` WHERE `SpellMiscId`=220;
DELETE FROM `areatrigger_template` WHERE `Id`=220;
DELETE FROM `areatrigger_template_actions` WHERE `AreaTriggerId`=220;
-- Blades of the Anointed give the "Unto Dust Thou Shalt Return" credit at Whitemane's corpse.
DELETE FROM `spell_script_names` WHERE `spell_id` IN (126787, 126843);

-- 6) The Hooded Crusader who appears after Whitemane also takes "Unto Dust Thou Shalt Return"
--    (the entrance crusader still does too).
DELETE FROM `creature_questender` WHERE `id`=64842 AND `quest`=31514;
